1	/**
2	 * PDFExportService
3	 *
4	 * Service for exporting receipts by category as a PDF with summary tables and receipt images
5	 * Specification: specs/specifications/category-receipt-pdf-export.md
6	 *
7	 * Traceable to:
8	 * - #{#cre2a} - PDF Document Structure (IMPLEMENTED)
9	 * - #{#cre2b} - PDF Data Formatting (IMPLEMENTED)
10	 * - #{#cre3a} - Receipt Image Handling (IMPLEMENTED)
11	 * - #{#cre3b} - PDF File Download Mechanism (IMPLEMENTED)
12	 * - #{#cre4b} - PDF Export Service Implementation (IMPLEMENTED)
13	 */
14	
15	import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
16	import type { PDFPage, PDFFont } from 'pdf-lib';
17	import type { Expense } from './ExpenseService';
18	import type { Category } from '$lib/types/Category';
19	
20	/**
21	 * #{#cre4b} PDF Export Options
22	 */
23	export interface PDFExportOptions {
24		categories: Category[];
25		dateRange: {
26			start: string;
27			end: string;
28		} | null;
29		onProgress?: (step: string, current: number, total: number) => void;
30		abortSignal?: AbortSignal;
31		fetchImageFn?: (path: string) => Promise<Uint8Array | null>;
32	}
33	
34	// #{#cre2a} US Letter page size (612 x 792 points)
35	const PAGE_WIDTH = 612;
36	const PAGE_HEIGHT = 792;
37	const MARGIN = 54; // 0.75 inches
38	const CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN;
39	
40	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
41	
42	/**
43	 * #{#cre4b} PDFExportService Class
44	 */
45	export class PDFExportService {
46		/**
47		 * #{#cre2b} Criterion 1: Format date as "MMM DD, YYYY"
48		 */
49		formatDate(dateString: string | null | undefined): string {
50			if (!dateString) return 'No Date';
51	
52			try {
53				let year: number, month: number, day: number;
54	
55				if (dateString.includes('T')) {
56					const date = new Date(dateString);
57					year = date.getUTCFullYear();
58					month = date.getUTCMonth();
59					day = date.getUTCDate();
60				} else {
61					const parts = dateString.split('-');
62					year = parseInt(parts[0]);
63					month = parseInt(parts[1]) - 1;
64					day = parseInt(parts[2]);
65				}
66	
67				const dayStr = String(day).padStart(2, '0');
68				return `${MONTHS[month]} ${dayStr}, ${year}`;
69			} catch {
70				return 'No Date';
71			}
72		}
73	
74		/**
75		 * #{#cre2b} Criteria 2, 3, 9: Format amount with $ sign, 2 decimals, comma separators
76		 */
77		formatAmount(amount: number | null | undefined): string {
78			if (amount === null || amount === undefined) return '$0.00';
79			const positive = Math.abs(amount);
80			const fixed = positive.toFixed(2);
81			const [whole, decimal] = fixed.split('.');
82			const withCommas = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
83			return `$${withCommas}.${decimal}`;
84		}
85	
86		/**
87		 * #{#cre2b} Criteria 6, 8: Format vendor name, handle missing
88		 */
89		formatVendorName(name: string | null | undefined): string {
90			if (!name || name.trim() === '') return 'Unknown Vendor';
91			return name.trim();
92		}
93	
94		/**
95		 * #{#cre2a} Criterion 3: Group expenses by category, sort alphabetically, sort by date within
96		 */
97		groupExpensesByCategory(expenses: Expense[]): Record<string, Expense[]> {
98			const groups: Record<string, Expense[]> = {};
99	
100			for (const expense of expenses) {
101				const categoryName = expense.category_name || 'Uncategorized';
102				if (!groups[categoryName]) {
103					groups[categoryName] = [];
104				}
105				groups[categoryName].push(expense);
106			}
107	
108			// Sort within each group by date ascending
109			for (const key of Object.keys(groups)) {
110				groups[key].sort((a, b) => {
111					const dateA = a.transaction_date || '';
112					const dateB = b.transaction_date || '';
113					return dateA.localeCompare(dateB);
114				});
115			}
116	
117			// Return as ordered object (alphabetical keys)
118			const sorted: Record<string, Expense[]> = {};
119			for (const key of Object.keys(groups).sort()) {
120				sorted[key] = groups[key];
121			}
122			return sorted;
123		}
124	
125		/**
126		 * #{#cre2a} Criterion 3: Calculate subtotal for a group of expenses
127		 */
128		calculateSubtotal(expenses: Expense[]): number {
129			return expenses.reduce((sum, e) => sum + Math.abs(e.total_amount ?? 0), 0);
130		}
131	
132		/**
133		 * #{#cre3b} Criteria 2-6: Generate filename based on categories and date range
134		 */
135		generateFilename(
136			categoryNames: string[],
137			dateRange: { start: string; end: string } | null
138		): string {
139			let categoryPart: string;
140			if (categoryNames.length === 1) {
141				categoryPart = categoryNames[0].replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
142			} else {
143				categoryPart = 'multiple_categories';
144			}
145	
146			let datePart: string;
147			if (dateRange) {
148				datePart = `${dateRange.start}_to_${dateRange.end}`;
149			} else {
150				datePart = 'all_time';
151			}
152	
153			return `receipts_${categoryPart}_${datePart}.pdf`;
154		}
155	
156		/**
157		 * #{#cre1a} #{#cre1b} #{#cre4a} Button enable/disable logic
158		 */
159		static shouldEnablePDFExport(state: {
160			filteredExpensesCount: number;
161			selectedCategoryIds: string[];
162			showUncategorizedOnly: boolean;
163			isExporting: boolean;
164		}): boolean {
165			if (state.isExporting) return false;
166			if (state.filteredExpensesCount === 0) return false;
167			if (state.selectedCategoryIds.length === 0) return false;
168			if (state.showUncategorizedOnly) return false;
169			return true;
170		}
171	
172		/**
173		 * #{#cre4b} Criterion 3: Generate the receipt PDF
174		 */
175		async generateReceiptPDF(expenses: Expense[], options: PDFExportOptions): Promise<Uint8Array> {
176			// #{#cre4b} Criterion 10: Check for cancellation
177			if (options.abortSignal?.aborted) {
178				throw new Error('PDF export aborted');
179			}
180	
181			const progress = options.onProgress || (() => {});
182			progress('Preparing receipt data...', 0, 1);
183	
184			const pdfDoc = await PDFDocument.create();
185			const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
186			const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
187	
188			// Group and sort
189			const groups = this.groupExpensesByCategory(expenses);
190			const categoryNames = Object.keys(groups);
191	
192			// ── Build summary table pages ─────────────────────────────
193	
194			let page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
195			let y = PAGE_HEIGHT - MARGIN;
196	
197			// Title
198			y = this.drawText(page, 'Receipt Export', fontBold, 18, MARGIN, y);
199			y -= 6;
200	
201			// Date range
202			const dateRangeText = options.dateRange
203				? `${this.formatDate(options.dateRange.start)} — ${this.formatDate(options.dateRange.end)}`
204				: 'All Time';
205			y = this.drawText(page, dateRangeText, font, 10, MARGIN, y);
206	
207			// Categories
208			const catListText = `Categories: ${categoryNames.join(', ')}`;
209			y = this.drawWrappedText(page, catListText, font, 10, MARGIN, y, CONTENT_WIDTH);
210	
211			// Generation date
212			const now = new Date();
213			const genDate = `Generated: ${MONTHS[now.getMonth()]} ${String(now.getDate()).padStart(2, '0')}, ${now.getFullYear()}`;
214			y = this.drawText(page, genDate, font, 10, MARGIN, y);
215			y -= 16;
216	
217			let grandTotal = 0;
218	
219			// Table column positions
220			const colNum = MARGIN;
221			const colDate = MARGIN + 30;
222			const colVendor = MARGIN + 140;
223			const colAmount = PAGE_WIDTH - MARGIN - 10;
224	
225			for (const categoryName of categoryNames) {
226				if (options.abortSignal?.aborted) throw new Error('PDF export aborted');
227	
228				const groupExpenses = groups[categoryName];
229				const subtotal = this.calculateSubtotal(groupExpenses);
230				grandTotal += subtotal;
231	
232				// Check if we need a new page (need at least ~100pt for header + 1 row + subtotal)
233				if (y < MARGIN + 100) {
234					page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
235					y = PAGE_HEIGHT - MARGIN;
236				}
237	
238				// Category heading
239				y = this.drawWrappedText(page, categoryName, fontBold, 14, MARGIN, y, CONTENT_WIDTH);
240				// Separator line
241				page.drawLine({
242					start: { x: MARGIN, y: y + 4 },
243					end: { x: PAGE_WIDTH - MARGIN, y: y + 4 },
244					thickness: 1,
245					color: rgb(0.7, 0.7, 0.7)
246				});
247				y -= 10;
248	
249				// Table header
250				this.drawText(page, '#', fontBold, 9, colNum, y);
251				this.drawText(page, 'Date', fontBold, 9, colDate, y);
252				this.drawText(page, 'Vendor', fontBold, 9, colVendor, y);
253				this.drawTextRight(page, 'Amount', fontBold, 9, colAmount, y);
254				y -= 14;
255	
256				// Table rows
257				const vendorMaxWidth = colAmount - colVendor - 60; // leave room for amount
258				for (let i = 0; i < groupExpenses.length; i++) {
259					if (y < MARGIN + 40) {
260						page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
261						y = PAGE_HEIGHT - MARGIN;
262					}
263	
264					const expense = groupExpenses[i];
265					const rowNum = String(i + 1);
266					const date = this.formatDate(expense.transaction_date);
267					const vendor = this.truncateText(
268						this.formatVendorName(expense.merchant_name),
269						font,
270						9,
271						vendorMaxWidth
272					);
273					const amount = this.formatAmount(expense.total_amount);
274	
275					this.drawText(page, rowNum, font, 9, colNum, y);
276					this.drawText(page, date, font, 9, colDate, y);
277					this.drawText(page, vendor, font, 9, colVendor, y);
278					this.drawTextRight(page, amount, font, 9, colAmount, y);
279					y -= 14;
280				}
281	
282				// Subtotal line
283				page.drawLine({
284					start: { x: colVendor, y: y + 12 },
285					end: { x: PAGE_WIDTH - MARGIN, y: y + 12 },
286					thickness: 0.5,
287					color: rgb(0.5, 0.5, 0.5)
288				});
289				this.drawText(page, 'Subtotal:', fontBold, 9, colVendor, y);
290				this.drawTextRight(page, this.formatAmount(subtotal), fontBold, 9, colAmount, y);
291				y -= 24;
292			}
293	
294			// Grand total
295			if (y < MARGIN + 40) {
296				page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
297				y = PAGE_HEIGHT - MARGIN;
298			}
299			page.drawLine({
300				start: { x: colVendor, y: y + 12 },
301				end: { x: PAGE_WIDTH - MARGIN, y: y + 12 },
302				thickness: 1.5,
303				color: rgb(0, 0, 0)
304			});
305			this.drawText(page, 'Grand Total:', fontBold, 11, colVendor, y);
306			this.drawTextRight(page, this.formatAmount(grandTotal), fontBold, 11, colAmount, y);
307	
308			// ── Receipt image pages ───────────────────────────────────
309	
310			const fetchImage = options.fetchImageFn || (async () => null);
311			let imageIndex = 0;
312			const totalImages = expenses.filter((e) => e.receipt_image_path).length || 1;
313	
314			for (const categoryName of categoryNames) {
315				if (options.abortSignal?.aborted) throw new Error('PDF export aborted');
316	
317				const groupExpenses = groups[categoryName];
318	
319				for (let i = 0; i < groupExpenses.length; i++) {
320					const expense = groupExpenses[i];
321					imageIndex++;
322					progress(`Loading images (${imageIndex} of ${totalImages})...`, imageIndex, totalImages);
323	
324					const imgPage = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
325					let imgY = PAGE_HEIGHT - MARGIN;
326	
327					// Category label
328					imgY = this.drawWrappedText(imgPage, categoryName, fontBold, 12, MARGIN, imgY, CONTENT_WIDTH);
329	
330					// Receipt reference header
331					const refText = `#${i + 1} — ${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`;
332					imgY = this.drawWrappedText(imgPage, refText, font, 10, MARGIN, imgY, CONTENT_WIDTH);
333					imgY -= 12;
334	
335					if (!expense.receipt_image_path) {
336						// Placeholder for missing image
337						imgY -= 40;
338						this.drawWrappedText(
339							imgPage,
340							`Receipt image unavailable — ${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`,
341							font,
342							11,
343							MARGIN,
344							imgY,
345							CONTENT_WIDTH
346						);
347						continue;
348					}
349	
350					try {
351						const imageBytes = await fetchImage(expense.receipt_image_path);
352						if (!imageBytes) {
353							imgY -= 40;
354							this.drawText(
355								imgPage,
356								`Receipt image unavailable — ${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`,
357								font,
358								11,
359								MARGIN,
360								imgY
361							);
362							continue;
363						}
364	
365						// Detect image type and embed
366						const image = await this.embedImage(pdfDoc, imageBytes);
367						if (image) {
368							const maxWidth = CONTENT_WIDTH;
369							const maxHeight = imgY - MARGIN;
370							const scale = Math.min(maxWidth / image.width, maxHeight / image.height, 1);
371							const width = image.width * scale;
372							const height = image.height * scale;
373							const x = MARGIN + (CONTENT_WIDTH - width) / 2;
374							const imageY = imgY - height;
375	
376							imgPage.drawImage(image, {
377								x,
378								y: imageY,
379								width,
380								height
381							});
382						}
383					} catch {
384						imgY -= 40;
385						this.drawWrappedText(
386							imgPage,
387							`Receipt image unavailable — ${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`,
388							font,
389							11,
390							MARGIN,
391							imgY,
392							CONTENT_WIDTH
393						);
394					}
395				}
396			}
397	
398			progress('Building PDF...', 1, 1);
399			return await pdfDoc.save();
400		}
401	
402		/**
403		 * #{#cre3b} Criterion 7, 8: Trigger browser download
404		 */
405		downloadPDF(pdfBytes: Uint8Array, filename: string): void {
406			const blob = new Blob([pdfBytes], { type: 'application/pdf' });
407			const link = document.createElement('a');
408			const url = URL.createObjectURL(blob);
409			link.setAttribute('href', url);
410			link.setAttribute('download', filename);
411			link.style.visibility = 'hidden';
412			document.body.appendChild(link);
413			link.click();
414			document.body.removeChild(link);
415			URL.revokeObjectURL(url);
416		}
417	
418		// ── Private helpers ──────────────────────────────────────────
419	
420		private drawText(
421			page: PDFPage,
422			text: string,
423			font: PDFFont,
424			size: number,
425			x: number,
426			y: number
427		): number {
428			page.drawText(text, { x, y, size, font, color: rgb(0, 0, 0) });
429			return y - size - 2;
430		}
431	
432		private drawWrappedText(
433			page: PDFPage,
434			text: string,
435			font: PDFFont,
436			size: number,
437			x: number,
438			y: number,
439			maxWidth: number
440		): number {
441			const words = text.split(' ');
442			let line = '';
443			const lineHeight = size + 2;
444	
445			for (const word of words) {
446				const testLine = line ? `${line} ${word}` : word;
447				const testWidth = font.widthOfTextAtSize(testLine, size);
448				if (testWidth > maxWidth && line) {
449					page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
450					y -= lineHeight;
451					line = word;
452				} else {
453					line = testLine;
454				}
455			}
456			if (line) {
457				page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
458				y -= lineHeight;
459			}
460			return y;
461		}
462	
463		private drawTextRight(
464			page: PDFPage,
465			text: string,
466			font: PDFFont,
467			size: number,
468			rightX: number,
469			y: number
470		): number {
471			const width = font.widthOfTextAtSize(text, size);
472			page.drawText(text, { x: rightX - width, y, size, font, color: rgb(0, 0, 0) });
473			return y - size - 2;
474		}
475	
476		private truncateText(text: string, font: PDFFont, size: number, maxWidth: number): string {
477			if (font.widthOfTextAtSize(text, size) <= maxWidth) return text;
478			const ellipsis = '...';
479			let truncated = text;
480			while (truncated.length > 0 && font.widthOfTextAtSize(truncated + ellipsis, size) > maxWidth) {
481				truncated = truncated.slice(0, -1);
482			}
483			return truncated + ellipsis;
484		}
485	
486		private async embedImage(pdfDoc: PDFDocument, imageBytes: Uint8Array) {
487			// Try JPEG first, then PNG
488			try {
489				return await pdfDoc.embedJpg(imageBytes);
490			} catch {
491				try {
492					return await pdfDoc.embedPng(imageBytes);
493				} catch {
494					return null;
495				}
496			}
497		}
498	}
