1	/**
2	 * PDFExportService Unit Tests
3	 *
4	 * Tests for PDF export functionality — category receipt export with grouped tables and images
5	 * Specification: specs/specifications/category-receipt-pdf-export.md
6	 *
7	 * Traceable to:
8	 * - #{#cre5a} - PDF Export Unit Tests
9	 * - #{#cre2a} - PDF Document Structure
10	 * - #{#cre2b} - PDF Data Formatting
11	 * - #{#cre3a} - Receipt Image Handling
12	 * - #{#cre3b} - PDF File Download Mechanism
13	 * - #{#cre4b} - PDF Export Service Implementation
14	 */
15	
16	import { describe, it, expect, vi, beforeEach } from 'vitest';
17	import type { Expense } from './ExpenseService';
18	
19	// ── Test data helpers ────────────────────────────────────────────────
20	
21	function makeExpense(overrides: Partial<Expense> = {}): Expense {
22		return {
23			receipt_id: 'r1',
24			merchant_name: 'Test Merchant',
25			total_amount: 100.0,
26			transaction_date: '2026-01-15',
27			receipt_image_path: 'user1/receipt1.jpg',
28			category_id: 'cat1',
29			categorization_source: 'manual',
30			category_name: 'Office Supplies',
31			category_color: '#FF0000',
32			matched_transaction_id: null,
33			...overrides
34		};
35	}
36	
37	// ── Tests ────────────────────────────────────────────────────────────
38	
39	describe('PDFExportService', () => {
40		let PDFExportService: any;
41		let service: any;
42	
43		beforeEach(async () => {
44			vi.clearAllMocks();
45			try {
46				const module = await import('./PDFExportService');
47				PDFExportService = module.PDFExportService;
48				service = new PDFExportService();
49			} catch {
50				PDFExportService = null;
51				service = null;
52			}
53		});
54	
55		// ── #{#cre2b} Date Formatting ──────────────────────────────────
56	
57		describe('formatDate', () => {
58			it('should format dates as "MMM DD, YYYY" (e.g., "Jan 05, 2026")', () => {
59				// #{#cre2b} Criterion 1 / #{#cre5a} Test 9
60				expect(service).not.toBeNull();
61				const result = service.formatDate('2026-01-05');
62				expect(result).toBe('Jan 05, 2026');
63			});
64	
65			it('should format dates with ISO timestamp correctly', () => {
66				// #{#cre2b} Criterion 1
67				expect(service).not.toBeNull();
68				const result = service.formatDate('2026-12-25T08:30:00Z');
69				expect(result).toBe('Dec 25, 2026');
70			});
71	
72			it('should return "No Date" for missing dates', () => {
73				// #{#cre2b} Criterion 10
74				expect(service).not.toBeNull();
75				expect(service.formatDate('')).toBe('No Date');
76				expect(service.formatDate(null)).toBe('No Date');
77				expect(service.formatDate(undefined)).toBe('No Date');
78			});
79	
80			it('should handle all 12 months correctly', () => {
81				// #{#cre2b} Criterion 1
82				expect(service).not.toBeNull();
83				const months = [
84					['2026-01-15', 'Jan 15, 2026'],
85					['2026-02-15', 'Feb 15, 2026'],
86					['2026-03-15', 'Mar 15, 2026'],
87					['2026-04-15', 'Apr 15, 2026'],
88					['2026-05-15', 'May 15, 2026'],
89					['2026-06-15', 'Jun 15, 2026'],
90					['2026-07-15', 'Jul 15, 2026'],
91					['2026-08-15', 'Aug 15, 2026'],
92					['2026-09-15', 'Sep 15, 2026'],
93					['2026-10-15', 'Oct 15, 2026'],
94					['2026-11-15', 'Nov 15, 2026'],
95					['2026-12-15', 'Dec 15, 2026']
96				];
97				for (const [input, expected] of months) {
98					expect(service.formatDate(input)).toBe(expected);
99				}
100			});
101		});
102	
103		// ── #{#cre2b} Amount Formatting ────────────────────────────────
104	
105		describe('formatAmount', () => {
106			it('should format amounts with dollar sign and 2 decimals', () => {
107				// #{#cre2b} Criterion 2 / #{#cre5a} Test 8
108				expect(service).not.toBeNull();
109				expect(service.formatAmount(125.99)).toBe('$125.99');
110			});
111	
112			it('should use comma separators for thousands', () => {
113				// #{#cre2b} Criterion 3
114				expect(service).not.toBeNull();
115				expect(service.formatAmount(1234.56)).toBe('$1,234.56');
116				expect(service.formatAmount(1000000)).toBe('$1,000,000.00');
