/**
 * PDFExportService
 *
 * Service for exporting receipts by category as a PDF with summary tables and receipt images
 * Specification: specs/specifications/category-receipt-pdf-export.md
 *
 * Traceable to:
 * - #{#cre2a} - PDF Document Structure (IMPLEMENTED)
 * - #{#cre2b} - PDF Data Formatting (IMPLEMENTED)
 * - #{#cre3a} - Receipt Image Handling (IMPLEMENTED)
 * - #{#cre3b} - PDF File Download Mechanism (IMPLEMENTED)
 * - #{#cre4b} - PDF Export Service Implementation (IMPLEMENTED)
 */

import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import type { PDFPage, PDFFont, PDFImage } from 'pdf-lib';
import type { Expense } from './ExpenseService';
import type { Category } from '$lib/types/Category';

type ProgressCallback = (step: string, current: number, total: number) => void;
type FetchImageFn = (path: string) => Promise<Uint8Array | null>;

/**
 * #{#cre4b} PDF Export Options
 */
export interface PDFExportOptions {
	categories: Category[];
	dateRange: {
		start: string;
		end: string;
	} | null;
	onProgress?: ProgressCallback;
	abortSignal?: AbortSignal;
	fetchImageFn?: FetchImageFn;
}

/** Fonts embedded once per document and shared by all drawing helpers */
interface PDFFonts {
	regular: PDFFont;
	bold: PDFFont;
}

/** Current page and vertical write position; mutated as content is drawn */
interface PageCursor {
	page: PDFPage;
	y: number;
}

// #{#cre2a} US Letter page size (612 x 792 points)
const PAGE_WIDTH = 612;
const PAGE_HEIGHT = 792;
const MARGIN = 54; // 0.75 inches
const CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN;

// Summary table column positions
const COL_NUM = MARGIN;
const COL_DATE = MARGIN + 30;
const COL_VENDOR = MARGIN + 140;
const COL_AMOUNT = PAGE_WIDTH - MARGIN - 10;

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * #{#cre4b} PDFExportService Class
 */
export class PDFExportService {
	/**
	 * #{#cre2b} Criterion 1: Format date as "MMM DD, YYYY"
	 */
	formatDate(dateString: string | null | undefined): string {
		if (!dateString) return 'No Date';

		try {
			let year: number, month: number, day: number;

			if (dateString.includes('T')) {
				const date = new Date(dateString);
				year = date.getUTCFullYear();
				month = date.getUTCMonth();
				day = date.getUTCDate();
			} else {
				const parts = dateString.split('-');
				year = parseInt(parts[0]);
				month = parseInt(parts[1]) - 1;
				day = parseInt(parts[2]);
			}

			const dayStr = String(day).padStart(2, '0');
			return `${MONTHS[month]} ${dayStr}, ${year}`;
		} catch {
			return 'No Date';
		}
	}

	/**
	 * #{#cre2b} Criteria 2, 3, 9: Format amount with $ sign, 2 decimals, comma separators
	 */
	formatAmount(amount: number | null | undefined): string {
		if (amount === null || amount === undefined) return '$0.00';
		const positive = Math.abs(amount);
		const fixed = positive.toFixed(2);
		const [whole, decimal] = fixed.split('.');
		const withCommas = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
		return `$${withCommas}.${decimal}`;
	}

	/**
	 * #{#cre2b} Criteria 6, 8: Format vendor name, handle missing
	 */
	formatVendorName(name: string | null | undefined): string {
		if (!name || name.trim() === '') return 'Unknown Vendor';
		return name.trim();
	}

	/**
	 * #{#cre2a} Criterion 3: Group expenses by category, sort alphabetically, sort by date within
	 */
	groupExpensesByCategory(expenses: Expense[]): Record<string, Expense[]> {
		const groups: Record<string, Expense[]> = {};

		for (const expense of expenses) {
			const categoryName = expense.category_name || 'Uncategorized';
			if (!groups[categoryName]) {
				groups[categoryName] = [];
			}
			groups[categoryName].push(expense);
		}

		// Sort within each group by date ascending
		for (const key of Object.keys(groups)) {
			groups[key].sort((a, b) => {
				const dateA = a.transaction_date || '';
				const dateB = b.transaction_date || '';
				return dateA.localeCompare(dateB);
			});
		}

		// Return as ordered object (alphabetical keys)
		const sorted: Record<string, Expense[]> = {};
		for (const key of Object.keys(groups).sort()) {
			sorted[key] = groups[key];
		}
		return sorted;
	}

	/**
	 * #{#cre2a} Criterion 3: Calculate subtotal for a group of expenses
	 */
	calculateSubtotal(expenses: Expense[]): number {
		return expenses.reduce((sum, e) => sum + Math.abs(e.total_amount ?? 0), 0);
	}

	/**
	 * #{#cre3b} Criteria 2-6: Generate filename based on categories and date range
	 */
	generateFilename(
		categoryNames: string[],
		dateRange: { start: string; end: string } | null
	): string {
		let categoryPart: string;
		if (categoryNames.length === 1) {
			categoryPart = categoryNames[0].replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
		} else {
			categoryPart = 'multiple_categories';
		}

		let datePart: string;
		if (dateRange) {
			datePart = `${dateRange.start}_to_${dateRange.end}`;
		} else {
			datePart = 'all_time';
		}

		return `receipts_${categoryPart}_${datePart}.pdf`;
	}

	/**
	 * #{#cre1a} #{#cre1b} #{#cre4a} Button enable/disable logic
	 */
	static shouldEnablePDFExport(state: {
		filteredExpensesCount: number;
		selectedCategoryIds: string[];
		showUncategorizedOnly: boolean;
		isExporting: boolean;
	}): boolean {
		if (state.isExporting) return false;
		if (state.filteredExpensesCount === 0) return false;
		if (state.selectedCategoryIds.length === 0) return false;
		if (state.showUncategorizedOnly) return false;
		return true;
	}

	/**
	 * #{#cre4b} Criterion 3: Generate the receipt PDF
	 */
	async generateReceiptPDF(expenses: Expense[], options: PDFExportOptions): Promise<Uint8Array> {
		// #{#cre4b} Criterion 10: Check for cancellation
		this.throwIfAborted(options.abortSignal);

		const progress = options.onProgress || (() => {});
		progress('Preparing receipt data...', 0, 1);

		const pdfDoc = await PDFDocument.create();
		const fonts: PDFFonts = {
			regular: await pdfDoc.embedFont(StandardFonts.Helvetica),
			bold: await pdfDoc.embedFont(StandardFonts.HelveticaBold)
		};

		// Group and sort
		const groups = this.groupExpensesByCategory(expenses);

		this.drawSummaryPages(pdfDoc, groups, fonts, options);
		await this.drawReceiptImagePages(pdfDoc, groups, fonts, options, progress);

		progress('Building PDF...', 1, 1);
		return await pdfDoc.save();
	}

	/**
	 * #{#cre3b} Criterion 7, 8: Trigger browser download
	 */
	downloadPDF(pdfBytes: Uint8Array, filename: string): void {
		// Copy into a fresh Uint8Array so the backing buffer is a plain ArrayBuffer,
		// which is what BlobPart requires (pdf-lib bytes are typed over ArrayBufferLike).
		const blob = new Blob([new Uint8Array(pdfBytes)], { type: 'application/pdf' });
		const link = document.createElement('a');
		const url = URL.createObjectURL(blob);
		link.setAttribute('href', url);
		link.setAttribute('download', filename);
		link.style.visibility = 'hidden';
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);
		URL.revokeObjectURL(url);
	}

	// ── Private helpers: page layout ─────────────────────────────

	private throwIfAborted(signal?: AbortSignal): void {
		if (signal?.aborted) throw new Error('PDF export aborted');
	}

	private startPage(pdfDoc: PDFDocument): PageCursor {
		return { page: pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]), y: PAGE_HEIGHT - MARGIN };
	}

	/** Start a new page if fewer than `minY` points remain on the current one */
	private ensureRoom(pdfDoc: PDFDocument, cursor: PageCursor, minY: number): void {
		if (cursor.y < minY) {
			cursor.page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
			cursor.y = PAGE_HEIGHT - MARGIN;
		}
	}

	// ── Private helpers: summary table pages ─────────────────────

	private drawSummaryPages(
		pdfDoc: PDFDocument,
		groups: Record<string, Expense[]>,
		fonts: PDFFonts,
		options: PDFExportOptions
	): void {
		const categoryNames = Object.keys(groups);
		const cursor = this.startPage(pdfDoc);

		this.drawSummaryHeader(cursor, categoryNames, fonts, options.dateRange);

		let grandTotal = 0;
		for (const categoryName of categoryNames) {
			this.throwIfAborted(options.abortSignal);
			grandTotal += this.drawCategoryTable(
				pdfDoc,
				cursor,
				categoryName,
				groups[categoryName],
				fonts
			);
		}

		this.drawGrandTotal(pdfDoc, cursor, grandTotal, fonts);
	}

	private drawSummaryHeader(
		cursor: PageCursor,
		categoryNames: string[],
		fonts: PDFFonts,
		dateRange: PDFExportOptions['dateRange']
	): void {
		// Title
		cursor.y = this.drawText(cursor.page, 'Receipt Export', fonts.bold, 18, MARGIN, cursor.y);
		cursor.y -= 6;

		// Date range
		const dateRangeText = dateRange
			? `${this.formatDate(dateRange.start)} — ${this.formatDate(dateRange.end)}`
			: 'All Time';
		cursor.y = this.drawText(cursor.page, dateRangeText, fonts.regular, 10, MARGIN, cursor.y);

		// Categories
		const catListText = `Categories: ${categoryNames.join(', ')}`;
		cursor.y = this.drawWrappedText(
			cursor.page,
			catListText,
			fonts.regular,
			10,
			MARGIN,
			cursor.y,
			CONTENT_WIDTH
		);

		// Generation date
		const now = new Date();
		const genDate = `Generated: ${MONTHS[now.getMonth()]} ${String(now.getDate()).padStart(2, '0')}, ${now.getFullYear()}`;
		cursor.y = this.drawText(cursor.page, genDate, fonts.regular, 10, MARGIN, cursor.y);
		cursor.y -= 16;
	}

	/** Draw one category's heading, rows, and subtotal. Returns the subtotal. */
	private drawCategoryTable(
		pdfDoc: PDFDocument,
		cursor: PageCursor,
		categoryName: string,
		expenses: Expense[],
		fonts: PDFFonts
	): number {
		// Need at least ~100pt for header + 1 row + subtotal
		this.ensureRoom(pdfDoc, cursor, MARGIN + 100);

		// Category heading
		cursor.y = this.drawWrappedText(
			cursor.page,
			categoryName,
			fonts.bold,
			14,
			MARGIN,
			cursor.y,
			CONTENT_WIDTH
		);
		// Separator line
		cursor.page.drawLine({
			start: { x: MARGIN, y: cursor.y + 4 },
			end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 4 },
			thickness: 1,
			color: rgb(0.7, 0.7, 0.7)
		});
		cursor.y -= 10;

		// Table header
		this.drawText(cursor.page, '#', fonts.bold, 9, COL_NUM, cursor.y);
		this.drawText(cursor.page, 'Date', fonts.bold, 9, COL_DATE, cursor.y);
		this.drawText(cursor.page, 'Vendor', fonts.bold, 9, COL_VENDOR, cursor.y);
		this.drawTextRight(cursor.page, 'Amount', fonts.bold, 9, COL_AMOUNT, cursor.y);
		cursor.y -= 14;

		// Table rows
		for (let i = 0; i < expenses.length; i++) {
			this.ensureRoom(pdfDoc, cursor, MARGIN + 40);
			this.drawExpenseRow(cursor, expenses[i], i + 1, fonts);
		}

		// Subtotal line
		const subtotal = this.calculateSubtotal(expenses);
		cursor.page.drawLine({
			start: { x: COL_VENDOR, y: cursor.y + 12 },
			end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 12 },
			thickness: 0.5,
			color: rgb(0.5, 0.5, 0.5)
		});
		this.drawText(cursor.page, 'Subtotal:', fonts.bold, 9, COL_VENDOR, cursor.y);
		this.drawTextRight(cursor.page, this.formatAmount(subtotal), fonts.bold, 9, COL_AMOUNT, cursor.y);
		cursor.y -= 24;

		return subtotal;
	}

	private drawExpenseRow(
		cursor: PageCursor,
		expense: Expense,
		rowNumber: number,
		fonts: PDFFonts
	): void {
		const vendorMaxWidth = COL_AMOUNT - COL_VENDOR - 60; // leave room for amount
		const date = this.formatDate(expense.transaction_date);
		const vendor = this.truncateText(
			this.formatVendorName(expense.merchant_name),
			fonts.regular,
			9,
			vendorMaxWidth
		);
		const amount = this.formatAmount(expense.total_amount);

		this.drawText(cursor.page, String(rowNumber), fonts.regular, 9, COL_NUM, cursor.y);
		this.drawText(cursor.page, date, fonts.regular, 9, COL_DATE, cursor.y);
		this.drawText(cursor.page, vendor, fonts.regular, 9, COL_VENDOR, cursor.y);
		this.drawTextRight(cursor.page, amount, fonts.regular, 9, COL_AMOUNT, cursor.y);
		cursor.y -= 14;
	}

	private drawGrandTotal(
		pdfDoc: PDFDocument,
		cursor: PageCursor,
		grandTotal: number,
		fonts: PDFFonts
	): void {
		this.ensureRoom(pdfDoc, cursor, MARGIN + 40);
		cursor.page.drawLine({
			start: { x: COL_VENDOR, y: cursor.y + 12 },
			end: { x: PAGE_WIDTH - MARGIN, y: cursor.y + 12 },
			thickness: 1.5,
			color: rgb(0, 0, 0)
		});
		this.drawText(cursor.page, 'Grand Total:', fonts.bold, 11, COL_VENDOR, cursor.y);
		this.drawTextRight(
			cursor.page,
			this.formatAmount(grandTotal),
			fonts.bold,
			11,
			COL_AMOUNT,
			cursor.y
		);
	}

	// ── Private helpers: receipt image pages ─────────────────────

	private async drawReceiptImagePages(
		pdfDoc: PDFDocument,
		groups: Record<string, Expense[]>,
		fonts: PDFFonts,
		options: PDFExportOptions,
		progress: ProgressCallback
	): Promise<void> {
		const fetchImage: FetchImageFn = options.fetchImageFn || (async () => null);
		const allExpenses = Object.values(groups).flat();
		const totalImages = allExpenses.filter((e) => e.receipt_image_path).length || 1;
		let imageIndex = 0;

		for (const [categoryName, groupExpenses] of Object.entries(groups)) {
			this.throwIfAborted(options.abortSignal);

			for (let i = 0; i < groupExpenses.length; i++) {
				imageIndex++;
				progress(`Loading images (${imageIndex} of ${totalImages})...`, imageIndex, totalImages);
				await this.drawReceiptImagePage(
					pdfDoc,
					categoryName,
					groupExpenses[i],
					i + 1,
					fonts,
					fetchImage
				);
			}
		}
	}

	/** One page per receipt: category label, reference header, then the image or a placeholder */
	private async drawReceiptImagePage(
		pdfDoc: PDFDocument,
		categoryName: string,
		expense: Expense,
		receiptNumber: number,
		fonts: PDFFonts,
		fetchImage: FetchImageFn
	): Promise<void> {
		const cursor = this.startPage(pdfDoc);

		// Category label
		cursor.y = this.drawWrappedText(
			cursor.page,
			categoryName,
			fonts.bold,
			12,
			MARGIN,
			cursor.y,
			CONTENT_WIDTH
		);

		// Receipt reference header
		const refText = `#${receiptNumber} — ${this.receiptSummaryText(expense)}`;
		cursor.y = this.drawWrappedText(
			cursor.page,
			refText,
			fonts.regular,
			10,
			MARGIN,
			cursor.y,
			CONTENT_WIDTH
		);
		cursor.y -= 12;

		if (!expense.receipt_image_path) {
			this.drawImageUnavailable(cursor, expense, fonts, true);
			return;
		}

		try {
			const imageBytes = await fetchImage(expense.receipt_image_path);
			if (!imageBytes) {
				this.drawImageUnavailable(cursor, expense, fonts, false);
				return;
			}

			// Detect image type and embed
			const image = await this.embedImage(pdfDoc, imageBytes);
			if (image) {
				this.drawScaledImage(cursor, image);
			}
		} catch {
			this.drawImageUnavailable(cursor, expense, fonts, true);
		}
	}

	private receiptSummaryText(expense: Expense): string {
		return `${this.formatVendorName(expense.merchant_name)} — ${this.formatDate(expense.transaction_date)} — ${this.formatAmount(expense.total_amount)}`;
	}

	private drawImageUnavailable(
		cursor: PageCursor,
		expense: Expense,
		fonts: PDFFonts,
		wrap: boolean
	): void {
		cursor.y -= 40;
		const message = `Receipt image unavailable — ${this.receiptSummaryText(expense)}`;
		if (wrap) {
			this.drawWrappedText(cursor.page, message, fonts.regular, 11, MARGIN, cursor.y, CONTENT_WIDTH);
		} else {
			this.drawText(cursor.page, message, fonts.regular, 11, MARGIN, cursor.y);
		}
	}

	/** Scale the image to fit the remaining page area (never upscale) and centre it horizontally */
	private drawScaledImage(cursor: PageCursor, image: PDFImage): void {
		const maxHeight = cursor.y - MARGIN;
		const scale = Math.min(CONTENT_WIDTH / image.width, maxHeight / image.height, 1);
		const width = image.width * scale;
		const height = image.height * scale;
		const x = MARGIN + (CONTENT_WIDTH - width) / 2;

		cursor.page.drawImage(image, {
			x,
			y: cursor.y - height,
			width,
			height
		});
	}

	// ── Private helpers: text primitives ─────────────────────────

	private drawText(
		page: PDFPage,
		text: string,
		font: PDFFont,
		size: number,
		x: number,
		y: number
	): number {
		page.drawText(text, { x, y, size, font, color: rgb(0, 0, 0) });
		return y - size - 2;
	}

	private drawWrappedText(
		page: PDFPage,
		text: string,
		font: PDFFont,
		size: number,
		x: number,
		y: number,
		maxWidth: number
	): number {
		const words = text.split(' ');
		let line = '';
		const lineHeight = size + 2;

		for (const word of words) {
			const testLine = line ? `${line} ${word}` : word;
			const testWidth = font.widthOfTextAtSize(testLine, size);
			if (testWidth > maxWidth && line) {
				page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
				y -= lineHeight;
				line = word;
			} else {
				line = testLine;
			}
		}
		if (line) {
			page.drawText(line, { x, y, size, font, color: rgb(0, 0, 0) });
			y -= lineHeight;
		}
		return y;
	}

	private drawTextRight(
		page: PDFPage,
		text: string,
		font: PDFFont,
		size: number,
		rightX: number,
		y: number
	): number {
		const width = font.widthOfTextAtSize(text, size);
		page.drawText(text, { x: rightX - width, y, size, font, color: rgb(0, 0, 0) });
		return y - size - 2;
	}

	private truncateText(text: string, font: PDFFont, size: number, maxWidth: number): string {
		if (font.widthOfTextAtSize(text, size) <= maxWidth) return text;
		const ellipsis = '...';
		let truncated = text;
		while (truncated.length > 0 && font.widthOfTextAtSize(truncated + ellipsis, size) > maxWidth) {
			truncated = truncated.slice(0, -1);
		}
		return truncated + ellipsis;
	}

	private async embedImage(pdfDoc: PDFDocument, imageBytes: Uint8Array): Promise<PDFImage | null> {
		// Try JPEG first, then PNG
		try {
			return await pdfDoc.embedJpg(imageBytes);
		} catch {
			try {
				return await pdfDoc.embedPng(imageBytes);
			} catch {
				return null;
			}
		}
	}
}

