import type { Expense } from './ExpenseService';
import { makeExpense } from '$lib/tests/builders/rowBuilders';

// ── Tests ────────────────────────────────────────────────────────────

describe('PDFExportService', () => {
	let service: PDFExportService;

	beforeEach(() => {
		service = new PDFExportService();
	});

	// ── #{#cre2b} Date Formatting ──────────────────────────────────

	describe('formatDate', () => {
		it('should format dates as "MMM DD, YYYY" (e.g., "Jan 05, 2026")', () => {
			// #{#cre2b} Criterion 1 / #{#cre5a} Test 9
			const result = service.formatDate('2026-01-05');
			expect(result).toBe('Jan 05, 2026');
		});

		it('should format dates with ISO timestamp correctly', () => {
			// #{#cre2b} Criterion 1
			const result = service.formatDate('2026-12-25T08:30:00Z');
			expect(result).toBe('Dec 25, 2026');
		});

		it('should return "No Date" for missing dates', () => {
			// #{#cre2b} Criterion 10
			expect(service.formatDate('')).toBe('No Date');
			expect(service.formatDate(null)).toBe('No Date');
			expect(service.formatDate(undefined)).toBe('No Date');
		});

		it('should handle all 12 months correctly', () => {
			// #{#cre2b} Criterion 1
			const months = [
				['2026-01-15', 'Jan 15, 2026'],
				['2026-02-15', 'Feb 15, 2026'],
				['2026-03-15', 'Mar 15, 2026'],
				['2026-04-15', 'Apr 15, 2026'],
