				['2026-06-15', 'Jun 15, 2026'],
				['2026-07-15', 'Jul 15, 2026'],
				['2026-08-15', 'Aug 15, 2026'],
				['2026-09-15', 'Sep 15, 2026'],
				['2026-10-15', 'Oct 15, 2026'],
				['2026-11-15', 'Nov 15, 2026'],
				['2026-12-15', 'Dec 15, 2026']
			];
			for (const [input, expected] of months) {
				expect(service.formatDate(input)).toBe(expected);
			}
		});
	});

	// ── #{#cre2b} Amount Formatting ────────────────────────────────

	describe('formatAmount', () => {
		it('should format amounts with dollar sign and 2 decimals', () => {
			// #{#cre2b} Criterion 2 / #{#cre5a} Test 8
			expect(service.formatAmount(125.99)).toBe('$125.99');
		});

		it('should use comma separators for thousands', () => {
			// #{#cre2b} Criterion 3
			expect(service.formatAmount(1234.56)).toBe('$1,234.56');
			expect(service.formatAmount(1000000)).toBe('$1,000,000.00');
		});

		it('should convert negative amounts to positive', () => {
			// #{#cre2b} Criterion 2
			expect(service.formatAmount(-25.5)).toBe('$25.50');
		});

		it('should handle zero amount', () => {
			// #{#cre2b} Criterion 9
			expect(service.formatAmount(0)).toBe('$0.00');
		});

		it('should handle null/undefined amounts as $0.00', () => {
			// #{#cre2b} Criterion 9
			expect(service.formatAmount(null)).toBe('$0.00');
			expect(service.formatAmount(undefined)).toBe('$0.00');
		});

		it('should round to 2 decimal places', () => {
			// #{#cre2b} Criterion 2
