	// ── #{#cre4b} PDF Generation (integration with pdf-lib) ───────

	describe('generateReceiptPDF', () => {
		it('should return a Uint8Array (valid PDF bytes)', async () => {
			// #{#cre4b} Criterion 3 / #{#cre5a} Test 2
			const expenses: Expense[] = [makeExpense()];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: { start: '2026-01-01', end: '2026-12-31' }
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should start with PDF magic bytes (%PDF)', async () => {
			// #{#cre2a} Criterion 6 / #{#cre5a} Test 2
			const expenses: Expense[] = [makeExpense()];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: { start: '2026-01-01', end: '2026-12-31' }
			});
			// PDF files start with %PDF
			const header = String.fromCharCode(result[0], result[1], result[2], result[3]);
			expect(header).toBe('%PDF');
		});

		it('should generate PDF with multiple categories grouped separately', async () => {
			// #{#cre2a} Criterion 3 / #{#cre5a} Test 4
			const expenses: Expense[] = [
				makeExpense({
					receipt_id: 'r1',
					category_name: 'Office Supplies',
					merchant_name: 'Staples',
					total_amount: 45.5,
					receipt_image_path: undefined
				}),
				makeExpense({
					receipt_id: 'r2',
					category_name: 'Repairs',
					merchant_name: 'Home Hardware',
					total_amount: 312.0,
					receipt_image_path: undefined
				})
			];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [
					{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' },
					{ id: 'cat2', family_id: 'f1', name: 'Repairs', color: '#00FF00' }
				],
				dateRange: null
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should call onProgress callback during generation', async () => {
			// #{#cre4b} Criterion 9 / #{#cre5a} Test 15
			const progressCalls: { step: string; current: number; total: number }[] = [];
			const expenses: Expense[] = [makeExpense({ receipt_image_path: undefined })];
			await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				onProgress: (step: string, current: number, total: number) => {
					progressCalls.push({ step, current, total });
				}
			});
			expect(progressCalls.length).toBeGreaterThan(0);
			// Should have at least a "Preparing" and "Building PDF" step
			expect(progressCalls.some((c) => c.step.toLowerCase().includes('prepar'))).toBe(true);
		});

		it('should call fetchImageFn for each expense with a receipt_image_path', async () => {
			// #{#cre3a} Criterion 1 / #{#cre5a} Test 3
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockResolvedValue(null);
			const expenses: Expense[] = [
				makeExpense({ receipt_id: 'r1', receipt_image_path: 'user1/img1.jpg' }),
				makeExpense({ receipt_id: 'r2', receipt_image_path: 'user1/img2.jpg' }),
				makeExpense({ receipt_id: 'r3', receipt_image_path: undefined })
			];
			await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			// Should be called for the 2 expenses with images, not the one without
			expect(fetchImageFn).toHaveBeenCalledTimes(2);
			expect(fetchImageFn).toHaveBeenCalledWith('user1/img1.jpg');
			expect(fetchImageFn).toHaveBeenCalledWith('user1/img2.jpg');
		});

		it('should still produce valid PDF when image fetch fails', async () => {
			// #{#cre3a} Criterion 9 / #{#cre5a} Test 13
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockRejectedValue(new Error('Network error'));
			const expenses: Expense[] = [makeExpense({ receipt_image_path: 'user1/broken.jpg' })];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			// PDF should still be valid despite fetch failure
			expect(result).toBeInstanceOf(Uint8Array);
			const header = String.fromCharCode(result[0], result[1], result[2], result[3]);
			expect(header).toBe('%PDF');
		});

		it('should still produce valid PDF when fetchImageFn returns null', async () => {
			// #{#cre3a} Criterion 9 / #{#cre5a} Test 5
			const fetchImageFn = vi.fn<(path: string) => Promise<Uint8Array | null>>();
			fetchImageFn.mockResolvedValue(null);
			const expenses: Expense[] = [makeExpense({ receipt_image_path: 'user1/missing.jpg' })];
			const result = await service.generateReceiptPDF(expenses, {
				categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
				dateRange: null,
				fetchImageFn
			});
			expect(result).toBeInstanceOf(Uint8Array);
			expect(result.length).toBeGreaterThan(0);
		});

		it('should support cancellation via AbortSignal', async () => {
			// #{#cre4b} Criterion 10 / #{#cre5a} Test 14
			const controller = new AbortController();
			controller.abort(); // Abort immediately

			const expenses: Expense[] = [makeExpense({ receipt_image_path: undefined })];
			await expect(
				service.generateReceiptPDF(expenses, {
					categories: [{ id: 'cat1', family_id: 'f1', name: 'Office Supplies', color: '#FF0000' }],
					dateRange: null,
					abortSignal: controller.signal
				})
			).rejects.toThrow(/abort|cancel/i);
		});
	});

